// ======================== UI Logic ========================
let currentGrammarSet=1, currentReadingSet=1, currentWritingSet=1, currentSpeakingSet=1;

// Grammar Engine
function loadGrammarSet(setNum){
    const set = grammarData[setNum];
    if(!set) return;
    let html = '';
    set.questions.forEach((q,i) => {
        html += `<div class="question"><p><strong>${i+1}.</strong> ${q}</p><div class="options">`;
        set.options[i].forEach(opt => { 
            let letter = opt.charAt(0); 
            html += `<label><input type="radio" name="q${i}" value="${letter}"> ${opt}</label>`; 
        });
        html += `</div></div>`;
    });
    document.getElementById('grammarQuestions').innerHTML = html;
    document.getElementById('submitGrammarBtn').style.display = 'block';
    document.getElementById('grammarResult').innerHTML = '';
}

function submitGrammar(){
    const set = grammarData[currentGrammarSet];
    let score = 0;
    for(let i=0; i<set.questions.length; i++){
        let sel = document.querySelector(`input[name="q${i}"]:checked`);
        if(sel && sel.value === set.answers[i]) score++;
    }
    document.getElementById('grammarResult').innerHTML = `<div class="result">🎯 Score: ${score} / ${set.questions.length} (${Math.round((score/set.questions.length)*100)}%)</div>`;
}

// Reading Engine
function loadReadingSet(setNum){
    const set = readingData[setNum];
    if(!set) return;
    let html = '';
    set.passages.forEach((pass, pIdx) => {
        html += `<div class="reading-passage"><h3>${pass.title}</h3><p>${pass.text}</p>`;
        pass.questions.forEach((q, qIdx) => {
            html += `<div class="question"><p><strong>${qIdx+1}.</strong> ${q}</p>
            <select id="read_${pIdx}_${qIdx}">
                <option value="">Select Answer</option>
                <option value="T">True (T)</option>
                <option value="F">False (F)</option>
                <option value="D">Doesn't Say (D)</option>
            </select></div>`;
        });
        html += `</div>`;
    });
    document.getElementById('readingQuestions').innerHTML = html;
    document.getElementById('submitReadingBtn').style.display = 'block';
    document.getElementById('readingResult').innerHTML = '';
}

function submitReading(){
    const set = readingData[currentReadingSet];
    let score = 0, total = 0;
    set.passages.forEach((pass, pIdx) => {
        pass.answers.forEach((ans, qIdx) => {
            total++;
            let sel = document.getElementById(`read_${pIdx}_${qIdx}`);
            if(sel && sel.value === ans) score++;
        });
    });
    document.getElementById('readingResult').innerHTML = `<div class="result">🎯 Score: ${score} / ${total} (${Math.round((score/total)*100)}%)</div>`;
}

